import XCTest
@testable import CheckmateCore
final class AuditRegressionTests:XCTestCase {
    func testNativeArchiveNormalizesUnknownLearningRecords()throws {var input=ApplicationState();input.course.lessonID="missing";input.course.step = -1;input.course.completed=["intro","missing"];input.course.answered=["missing:0"];var record=PuzzleProgress();record.attempts = -2;input.puzzles=["rook":record,"missing":record];var output=ApplicationState();let report=try LegacyImporter.apply(JSONEncoder().encode(input),to:&output,course:CourseLibrary());XCTAssertEqual(output.course.lessonID,"intro");XCTAssertEqual(output.course.step,0);XCTAssertEqual(output.course.completed,["intro"]);XCTAssertTrue(output.course.answered.isEmpty);XCTAssertNil(output.puzzles["missing"]);XCTAssertEqual(output.puzzles["rook"]?.attempts,0);XCTAssertFalse(report.adjusted.isEmpty);XCTAssertFalse(report.ignored.isEmpty);try StateStore.validate(output);XCTAssertThrowsError(try StateStore.validate(input))}
    @MainActor func testLessonEscapeAndNegativeSavedStep()throws {let s=try GameSession(engine:nil),p=try LearningPlayer(session:s);s.state.course.step = -1;p.openLesson(index:0);XCTAssertEqual(p.step,0);p.openPuzzle(id:"rook");p.click("d2");XCTAssertEqual(p.picked,["d2"]);p.clearSelection();XCTAssertTrue(p.picked.isEmpty)}
    @MainActor func testSupersededMicrophoneStartCannotDisconnectCoach()async throws {let s=try GameSession(engine:nil);s.state.settings.voiceMicrophone=false;s.state.settings.coachingMode="quiet";let v=try VoiceCoach(session:s);v.settingsChanged();v.automationCaptureStart={_ in try await Task.sleep(nanoseconds:100_000_000);throw CancellationError()};_ = try s.openVoice();v.receive(["type":"session.updated"]);s.state.settings.voiceMicrophone=true;v.settingsChanged();try await Task.sleep(nanoseconds:10_000_000);s.state.settings.voiceInputDevice="new";v.settingsChanged();try await Task.sleep(nanoseconds:150_000_000);XCTAssertTrue(v.connected);XCTAssertFalse(v.status.contains("unavailable"));s.state.settings.voiceInputDevice="third";v.settingsChanged();v.disconnect();try await Task.sleep(nanoseconds:150_000_000);XCTAssertEqual(v.status,"Disconnected");XCTAssertNil(s.voiceLease)}
    func testPartialImportCanBeRebasedAfterLiveProgressChanges()throws {let data=Data(#"{"checkmate-settings-v1":{"voiceLanguage":"ja"}}"#.utf8);var live=ApplicationState(),preview=live;let course=try CourseLibrary();_ = try LegacyImporter.apply(data,to:&preview,course:course);let game=try ChessRules();_ = try game.move("e2","e4");_ = try game.move("e7","e5");live.practice.pgn=game.pgn;live.practice.fen=game.fen;_ = try LegacyImporter.apply(data,to:&live,course:course);XCTAssertEqual(live.practice.pgn,game.pgn);XCTAssertEqual(live.settings.voiceLanguage,"ja")}
    @MainActor func testRepeatedMicrophoneTestDoesNotStopNewCapture()async throws {let s=try GameSession(engine:nil),v=try VoiceCoach(session:s);v.automationCaptureStart={_ in try await Task.sleep(nanoseconds:100_000_000)};v.testMicrophone();try await Task.sleep(nanoseconds:10_000_000);v.testMicrophone();try await Task.sleep(nanoseconds:150_000_000);XCTAssertEqual(v.status,"Microphone test — speak for five seconds");v.disconnect();try await Task.sleep(nanoseconds:20_000_000);XCTAssertEqual(v.status,"Disconnected")}

}
